KINDS = set('proposal accept confirm refuse paid dispute hardship support human restructure stop callback pause resume withdraw repeat question aside unknown'.split())
KEYS = set('k p a d t c u g r s'.split())
MONTHS = dict((x.lower(),i) for i,x in enumerate(['January','February','March','April','May','June','July','August','September','October','November','December'],1))
WEEK = ['monday','tuesday','wednesday','thursday','friday','saturday','sunday']
WORDS = dict(zip('zero one two three four five six seven eight nine ten eleven twelve thirteen fourteen fifteen sixteen seventeen eighteen nineteen twenty'.split(),range(21)))
ORDS = dict(zip('first second third fourth fifth sixth seventh eighth ninth tenth eleventh twelfth thirteenth fourteenth fifteenth sixteenth seventeenth eighteenth nineteenth twentieth'.split(),range(1,21)))
ORDS.update({'thirtieth':30,'thirty first':31,'twenty first':21,'twenty second':22,'twenty third':23,'twenty fourth':24,'twenty fifth':25,'twenty sixth':26,'twenty seventh':27,'twenty eighth':28,'twenty ninth':29})

def norm(x):
    return str(x or '').lower().replace('’',"'").replace('‘',"'").replace('“','"').replace('”','"').strip()

def yes(x):
    return str(x).lower() == 'true'

def business(d):
    return d.weekday()<5 and d.isoformat() not in HOLIDAYS

def after(d,n):
    for _ in range(40):
        d += datetime.timedelta(days=1)
        if business(d):
            n -= 1
            if n == 0: return d
    raise ValueError('calendar')

def nextbiz(d):
    for _ in range(40):
        if business(d): return d
        d += datetime.timedelta(days=1)
    raise ValueError('calendar')

def cents(x):
    s = str(x)
    if not re.fullmatch(r'[0-9]+(?:\.[0-9]{1,2})?',s): raise ValueError('amount must be finite plain EUR with at most two decimals')
    a,b = (s.split('.')+[''])[:2] if '.' in s else (s,'')
    return int(a)*100 + int((b+'00')[:2])

