def numberword(s):
    s = s.replace('-',' ').strip()
    if s.isdigit(): return int(s)
    if s in ORDS: return ORDS[s]
    if s in WORDS: return WORDS[s]
    w=s.split()
    if len(w)==2 and w[0] in ('twenty','thirty') and w[1] in WORDS: return (20 if w[0]=='twenty' else 30)+WORDS[w[1]]
    raise ValueError('number words')

def yearword(s):
    s=s.replace('-',' ').replace(',',' ').strip()
    s=re.sub(r'\s+',' ',s)
    if re.fullmatch(r'\d{4}',s): return int(s)
    if s.startswith('nineteen '): return 1900+numberword(s[9:])
    if s.startswith('twenty '):
        rem=s[7:]
        if rem.startswith('twenty '): return 2020+numberword(rem[7:])
        return 2000+numberword(rem)
    if s.startswith('two thousand'):
        rem=s[12:].strip()
        if rem.startswith('and '): rem=rem[4:]
        return 2000+(numberword(rem) if rem else 0)
    raise ValueError('year')

def datevalue(value,today,offer=''):
    s=norm(value)
    if not s or any(c in s for c in '[]{}"|;!') or s.endswith('...'): raise ValueError('unfinished or malformed date')
    if re.fullmatch(r'\d{4}-\d{2}-\d{2}',s): return datetime.date.fromisoformat(s)
    if s in ('today','tomorrow'): return today+datetime.timedelta(days=int(s=='tomorrow'))
    s=s.rstrip('.').replace(',',' ')
    s=re.sub(r'\s+',' ',s)
    s=re.sub(r'^(?:on|the) ','',s)
    s=re.sub(r'\b(\d+)(?:st|nd|rd|th)\b',r'\1',s)
    if s in WEEK or s.startswith(('this ','next ')) and s.split()[-1] in WEEK:
        w=WEEK.index(s.split()[-1])
        if s.startswith('this '): return today-datetime.timedelta(days=today.weekday())+datetime.timedelta(days=w)
        if s.startswith('next '): return today-datetime.timedelta(days=today.weekday())+datetime.timedelta(days=7+w)
        return today+datetime.timedelta(days=(w-today.weekday()-1)%7+1)
    weekday=None
    if s.split()[0] in WEEK:
        weekday=WEEK.index(s.split()[0]); s=' '.join(s.split()[1:]); s=re.sub(r'^the ','',s)
    parts=s.split(); found=[(i,MONTHS[p]) for i,p in enumerate(parts) if p in MONTHS]
    if len(found)==1:
        i,m=found[0]
        if i==0:
            tail=parts[1:]; y=today.year
            if tail and re.fullmatch(r'\d{4}',tail[-1]): y=int(tail.pop())
            day=numberword(' '.join(tail))
        else:
            day=numberword(' '.join(parts[:i])); y=yearword(' '.join(parts[i+1:])) if parts[i+1:] else today.year
        d=datetime.date(y,m,day)
    elif offer:
        day=numberword(s); o=datetime.date.fromisoformat(offer)
        if day!=o.day: raise ValueError('day conflicts with spoken offer')
        d=o
    else: raise ValueError('exact date missing')
    if weekday is not None and d.weekday()!=weekday: raise ValueError('weekday conflicts with date')
    return d

def decode(payload):
    if not isinstance(payload,str) or not payload.endswith('!') or payload.count('!')!=1: raise ValueError('event terminator')
    if payload=='!': return []
    if not payload.endswith(';!'): raise ValueError('row terminator')
    rows=[]
    for row in payload[:-2].split(';'):
        out={}
        for field in row.split('|'):
            if field.count('=')!=1: raise ValueError('tag separator')
            k,v=field.split('=')
            if k not in KEYS or k in out or not v: raise ValueError('unknown duplicate empty tag')
            if re.search(r'%(?!25|7C|3B|3D|21)',v): raise ValueError('escape')
            for a,b in [('%21','!'),('%3D','='),('%3B',';'),('%7C','|'),('%25','%')]: v=v.replace(a,b)
            out[k]=v
        if not set(['k','c','s']).issubset(out) or out['k'] not in KINDS or out['c'] not in ('0','1'): raise ValueError('required kind completion source')
        if 'u' in out and out['u'] not in ('amount','date','both','unknown'): raise ValueError('unfinished component')
        if 'g' in out and out['g'] not in ('shared','total','each'): raise ValueError('scope')
        if 'r' in out and not re.fullmatch(r'\d+',out['r']): raise ValueError('replacement row')
        if 'a' in out and out['a'] not in ('full','floor','offered'): cents(out['a'])
        if 't' in out and not re.fullmatch(r'\d{2}:\d{2}',out['t']): raise ValueError('time')
        rows.append(out)
    return rows

def recipient(raw,act,v):
