    if re.search(r'\b(?:wrong number|do not know|don\x27t know|not (?:his|her|their) number)\b',s): return 'wrong'
    if re.search(r'\b(?:he|she|member|'+re.escape(norm(v.get('first_name')))+r') (?:has died|died|is dead|passed away)\b',s): return 'deceased'
    if re.search(r'\b(?:this is|i am|i\x27m) (?:his|her|their|the member\x27s) (?:wife|husband|son|daughter|partner|mother|father|sister|brother)\b|\b(?:he|she)\x27?s (?:not here|at work|unavailable)|\b(?:he|she) is not (?:here|available)',s): return 'third'
    if act in ('wrong','deceased','third') and s: return act
