    cues=bool(re.search(r'\b(?:yes|speaking|that\x27s me|it\x27s me)\b',s))
    names=[n for n in names if n]
    namecue=any(re.search(r'(?<!\w)'+re.escape(n)+r'(?!\w)',s) for n in names)
    if re.search(r'\b(?:not me|i am not|i\x27m not|if i|if this|would be)\b',s): return 'unknown'
    match=re.search(r'\b(?:this is|i am|i\x27m)\s+([\w\x27-]+)',s)
    if match and match.group(1) not in names+[norm(v.get('title')).rstrip('.'),'the'] and not cues: return 'third'
    return 'self' if cues or namecue or act=='self' else 'unknown'

