    return '',buffer,'unreadable'

def resolver(ref,products,current):
    ref=norm(ref or 'current')
    if ref=='all': return [p['product_id'] for p in products]
    if ref=='loans': return [p['product_id'] for p in products if p['type']!='credit_card']
    if ref=='current': return [current] if current else []
    out=[]
    for token in ref.split(','):
        token=token.strip(); candidates=[]
        for p in products:
            aliases=[norm(p['product_id']),p['type'],p['type'].replace('_',' '),norm(p['label'])]
            if token in aliases: candidates.append(p['product_id'])
        if len(candidates)!=1: raise ValueError('unresolved product '+token)
        if candidates[0] in out: raise ValueError('duplicate target')
        out.extend(candidates)
    if not out: raise ValueError('missing target')
    return out

